 if(a==='clock'&&b==='apply'){state.season=document.getElementById('clockSeason')?.value||'winter';let v=document.getElementById('clockTime')?.value||'11:00';const m=/^(\d{2}):(\d{2})$/.exec(v);if(m){state.clockHour=Number(m[1]);state.clockMin=Number(m[2])}render();return}
 if(a==='flight'){if(b==='next'){state.flightIndex=(state.flightIndex+1)%FLIGHTS.length;state.flightResult=null;render();return}if(b==='check'){if(state.flightResult?.ok)return;let t=FLIGHTS[state.flightIndex%FLIGHTS.length],v=document.getElementById('flightAnswer')?.value,d=document.getElementById('flightDay')?.value,calc=flightCalc(t);let ok=v===calc.time&&d===calc.weekday;state.flightResult={ok,explanation:calc.explanation};if(ok){progress.stars+=4;save()}render();return}}
