function handleMap(e){const svg=e.target.closest('#workMap');if(!svg)return;let p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;let ctm=svg.getScreenCTM();if(!ctm)return;let z=p.matrixTransform(ctm.inverse());let x=Math.max(12,Math.min(728,Math.round(z.x))),y=Math.max(40,Math.min(413,Math.round(z.y)));progress.workMarks.push({tool:state.workTool,x,y});save();render()}
function updateHeightLive(value){const steep=Number(value),baseRadius=203-steep*1.46;state.heightVal=steep;const base=document.getElementById('heightBase');if(!base)return;base.setAttribute('rx',baseRadius);base.setAttribute('ry',(baseRadius*.60).toFixed(1));document.querySelectorAll('.height-contour').forEach(el=>{let h=Number(el.dataset.elevation),r=baseRadius*Math.sqrt(1-(h/850)**2);el.setAttribute('rx',r.toFixed(1));el.setAttribute('ry',(r*.6).toFixed(1))});let b=baseRadius*.9,pts=Array.from({length:53},(_,i)=>{let t=(i-26)/26,x=384+t*b,y=358-156*Math.sqrt(Math.max(0,1-t*t));return [x.toFixed(1),y.toFixed(1)]});document.getElementById('heightProfile')?.setAttribute('d','M'+pts.map(p=>p.join(' ')).join(' L')+' L'+(384+b).toFixed(1)+' 358 L'+(384-b).toFixed(1)+' 358 Z');const label=document.getElementById('heightSteep');if(label)label.textContent=steep<35?'flacher Hang':steep<65?'mittlerer Hang':'steiler Hang';const notice=document.getElementById('heightObservation');if(notice)notice.innerHTML='<b>Beobachtung:</b> '+(steep>=65?'Der Hang ist steil: Die Höhenlinien liegen auf der Karte dicht beieinander.':steep<=35?'Der Hang ist flach: Die Höhenlinien liegen weiter auseinander.':'Mit mittlerer Steilheit liegen die Höhenlinien in mittleren Abständen.')+' <b>Die Höhenwerte bleiben gleich.</b>'}
MAIN.addEventListener('click',e=>{const t=e.target.closest('[data-action]');if(t){action(t.dataset.action);return}if(e.target.closest('#workMap'))handleMap(e)});
MAIN.addEventListener('change',e=>{if(e.target.id==='heightRange'){state.heightVal=Number(e.target.value);render()}});
MAIN.addEventListener('input',e=>{if(e.target.id==='heightRange')updateHeightLive(e.target.value);if(e.target.id==='glossarySearch'){state.glossarySearch=e.target.value;let search=state.glossarySearch.toLocaleLowerCase('de');let el=document.getElementById('glossaryCards');el.innerHTML=GLOSSARY.filter(([w,d])=>(w+' '+d).toLocaleLowerCase('de').includes(search)).map(([w,d])=>`<div class="card slim"><h3>${w}</h3><p>${d}</p></div>`).join('')||'<p>Keinen passenden Begriff gefunden.</p>'}});
document.getElementById('tabs').addEventListener('click',e=>{const b=e.target.closest('button[data-tab]');if(b)switchTab(b.dataset.tab)});
document.getElementById('settingsButton').addEventListener('click',modal);
document.getElementById('overlay').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)action(b.dataset.action);else if(e.target.id==='overlay')closeModal()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.getElementById('overlay').hidden)closeModal()});
