function newArena(advanced=false){clearArenaClock();const pool=advanced?ADVANCED:arena.topic==='all'?Q:Q.filter(q=>q.topic===arena.topic);const questions=pickQuestions(pool,Math.min(arena.size,pool.length));arena={...arena,phase:'play',advanced,questions,idx:0,points:0,combo:0,results:[],selected:null,done:false,mistakes:0,clockFor:-1,deadline:0};render()}
function arenaCurrent(){return arena.questions[arena.idx]}
function arenaClock(){clearArenaClock();if(arena.phase!=='play'||arena.done||!arena.seconds)return;if(arena.clockFor!==arena.idx){arena.start=performance.now();arena.deadline=arena.start+arena.seconds*1000;arena.clockFor=arena.idx;}arena.remaining=Math.max(0,(arena.deadline-performance.now())/1000);arenaInterval=setInterval(()=>{if(state.tab!=='arena'){clearArenaClock();return}if(arena.done||arena.phase!=='play'){clearArenaClock();return}arena.remaining=Math.max(0,(arena.deadline-performance.now())/1000);let label=document.getElementById('arenaCountdown');if(label)label.textContent=Math.ceil(arena.remaining)+' s';let bar=document.getElementById('arenaFill');if(bar)bar.style.width=(arena.remaining/arena.seconds*100)+'%';if(arena.remaining<=0)answerArena(null)},90)}
function answerArena(choice){if(arena.done||arena.phase!=='play')return;const q=arenaCurrent();if(!q)return;clearArenaClock();arena.remaining=arena.seconds?Math.max(0,(arena.deadline-performance.now())/1000):0;arena.selected=choice;arena.done=true;const good=choice===q.answer;grade(q,good);if(good){arena.combo++;let pts=500+(arena.seconds?Math.round(500*arena.remaining/arena.seconds):0)+Math.min(4,arena.combo-1)*80;arena.points+=pts;arena.results.push({id:q.id,ok:true,pts})}else{arena.combo=0;arena.mistakes++;arena.results.push({id:q.id,ok:false,pts:0})}addBadges();render()}
function nextArena(){if(!arena.done)return;arena.idx++;arena.done=false;arena.selected=null;arena.clockFor=-1;arena.deadline=0;if(arena.idx>=arena.questions.length){arena.phase='results';clearArenaClock()}render()}
function arenaSetup(){return head('Wie bei einem Quizduell','Die Blitz-Quiz-Arena','Vier große Antwortfelder, Zeitwahl, Punkte und Serienbonus – allein spielbar, ganz ohne Anmeldung oder echte Mitspieler.')+`<section class="arena-hero"><h2>🏁 Bereit für die Erdkunde-Challenge?</h2><p>Entscheide selbst, ob du gegen die Zeit spielst. Zum Üben kannst du den Timer abschalten. Nach jeder Antwort erhältst du eine Erklärung.</p></section><div class="card" style="max-width:740px;margin-top:18px"><div class="twofields"><div class="field"><label for="arenaTopic">Fragenbereich</label><select id="arenaTopic" class="rw-select"><option value="all">Alle 16 Themen</option>${MODULES.map(m=>`<option value="${m.id}" ${arena.topic===m.id?'selected':''}>${esc(m.title)}</option>`).join('')}</select></div><div class="field"><label for="arenaSize">Fragen pro Runde</label><select id="arenaSize" class="rw-select">${[5,10,15].map(n=>`<option value="${n}" ${arena.size===n?'selected':''}>${n} Fragen</option>`).join('')}</select></div><div class="field"><label for="arenaSeconds">Zeit pro Frage</label><select id="arenaSeconds" class="rw-select">${[0,15,25,40].map(n=>`<option value="${n}" ${arena.seconds===n?'selected':''}>${secLabel(n)}</option>`).join('')}</select></div></div><div class="inline">${btn('▶ Quizduell starten','arena:start','btn alt')}${btn('🔬 Anspruchsvolle Denkfragen','arena:deep','btn ghost')}</div><div class="rw-note" style="margin-top:15px"><b>Faire Spielregeln:</b> Für eine richtige Antwort gibt es 500 Grundpunkte, bei Zeitwahl weitere Punkte für Schnelligkeit und einen Bonus für mehrere richtige Antworten hintereinander. Falsche Antworten kosten keine Sterne.</div></div>`}
function arenaView(){if(arena.phase==='setup')return arenaSetup();if(arena.phase==='results'){const c=arena.results.filter(r=>r.ok).length,all=arena.questions.length;return head('Rückmeldung','Geschafft! 🎉','Ein Quizduell bewertet nur diese Runde – es ist keine Schulnote.')+`<div class="card" style="max-width:790px;margin:auto"><div class="arena-result">${human(arena.points)} Punkte</div><h2 style="text-align:center">${c} von ${all} Aufgaben richtig</h2><div class="progress-track"><div class="progress-fill" style="width:${Math.round(c/all*100)}%"></div></div><p style="text-align:center">${c===all?'Alle Aufgaben gelöst!':c>=all*.7?'Du hast viele Zusammenhänge verstanden.':'Gut trainiert. Wir schauen uns Unsicherheiten noch einmal an.'}</p><div class="rw-note">${arena.mistakes} Aufgabe(n) solltest du noch einmal ansehen. Sie stehen auch im persönlichen Fehlertraining bereit.</div><div class="inline" style="margin-top:16px">${btn('Noch einmal spielen','arena:restart','btn alt')}${btn('Unsichere Aufgaben üben','start:review:all','btn ghost',progress.mistakes.length?'':'disabled')}${btn('Zur Forscherwerkstatt','tab:workshop','btn soft')}</div></div>`}
 const q=arenaCurrent(),i=arena.idx;return `<div class="space"><h1>⚡ Blitz-Quiz ${arena.advanced?'– Expertenrunde':''}</h1>${btn('← Runde beenden','arena:exit','btn ghost small')}</div><div class="arena-hero" style="margin-top:12px"><div class="rw-status"><b>Frage ${i+1} / ${arena.questions.length}</b><span>⭐ ${human(arena.points)} Punkte · 🔥 ${arena.combo}er-Serie</span></div><div class="arena-timer"><div id="arenaFill" style="width:${arena.seconds?100:0}%"></div></div><div class="rw-status"><span>${mod(q.topic).icon} ${esc(mod(q.topic).title)}</span><strong id="arenaCountdown">${arena.seconds?(arena.done?'Zeit gestoppt':arena.seconds+' s'):'Ohne Zeitdruck'}</strong></div></div><section class="card" style="margin-top:14px"><h2>${esc(q.text)}</h2><div class="arena-board">${q.opts.map((v,k)=>`<button type="button" class="arena-tile ${arena.done?(k===q.answer?'winning':k===arena.selected?'chosen-wrong':''):''}" ${arena.done?'disabled':''} aria-label="Antwort ${String.fromCharCode(65+k)}: ${esc(v)}" data-action="arena:answer:${k}"><span class="shape" aria-hidden="true">${['▲','◆','●','■'][k]}</span><span>${String.fromCharCode(65+k)} · ${esc(v)}</span></button>`).join('')}</div>${arena.done?`<div class="arena-message ${arena.selected===q.answer?'correct':'wrong'}" role="status" style="margin-top:16px"><b>${arena.selected===q.answer?'✅ Richtig – weiter so!':arena.selected===null?'⌛ Zeit vorbei.':'🔎 Fast! Hier ist die Erklärung:'}</b>${reasoningFor(q,arena.selected,FOCUS_IDS.includes(q.topic))}</div><div class="inline" style="margin-top:12px">${btn(i+1===arena.questions.length?'Auswertung öffnen →':'Nächste Frage →','arena:next','btn alt')}</div>`:`<p class="subtle mini">Antworte durch Antippen eines farbigen Feldes. Die vier Symbole helfen zusätzlich zur Farbe.</p>`}</section>`}

const MEMORY_SETS=[
 [['Äquator','0° Breite'],['Nullmeridian','0° Länge'],['Legende','Zeichen erklärt'],['Höhenlinie','Gleiche Höhe'],['Mercator','Winkeltreue Karte'],['Maßstab','Verkleinerung']],
 [['Senkrechtluftbild','Blick senkrecht von oben'],['Kompass','Richtung finden'],['Breitengrad','Nord oder Süd'],['Längengrad','Ost oder West'],['Ozean','Großes Weltmeer'],['Rotation','Drehung um eigene Achse']],
 [['Topografische Karte','Gelände und Wege'],['Thematische Karte','Ein bestimmtes Thema'],['Tageszeit','Ortsabhängige Uhrzeit'],['Stern','Leuchtet selbst'],['Planet','Umläuft einen Stern'],['Kartenzeichen','Signatur']]
];
let memory={deck:[],open:[],solved:[],turns:0,locked:false,finished:false,pack:0};
function shuffleArray(a){let out=[...a];for(let i=out.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]]}return out}
function newMemory(){const set=MEMORY_SETS[memory.pack%MEMORY_SETS.length];memory={...memory,deck:shuffleArray(set.flatMap((p,i)=>[{id:i,label:p[0]},{id:i,label:p[1]}])),open:[],solved:[],turns:0,locked:false,finished:false};render()}
function memoryPick(i){if(memory.solved.includes(i)||memory.locked||memory.finished)return;if(memory.open.length===2){memory.open=[]}if(memory.open.includes(i))return;memory.open.push(i);if(memory.open.length===2){memory.turns++;const [a,b]=memory.open;if(memory.deck[a].id===memory.deck[b].id){memory.solved.push(a,b);memory.open=[];progress.stars+=2;save();memory.finished=memory.solved.length===memory.deck.length}}render()}
function memoryView(){return head('Wissen spielerisch verbinden','Geo-Memo','Decke jeweils zwei Karten auf und verbinde einen Fachbegriff mit seiner passenden Erklärung.')+`<div class="card" style="max-width:900px;margin:auto"><div class="space"><span class="arena-pill">${memory.solved.length/2} / 6 Paare</span><span class="arena-pill">${memory.turns} Versuche</span></div><div class="memory-board">${memory.deck.map((x,i)=>{const show=memory.open.includes(i)||memory.solved.includes(i);return `<button type="button" data-action="memory:pick:${i}" ${memory.solved.includes(i)?'disabled':''} aria-pressed="${show}" aria-label="Karte ${i+1}: ${show?esc(x.label):'verdeckt'}" class="memory-tile ${memory.solved.includes(i)?'solved':''}">${show?esc(x.label):'<span class="memory-back">🌍</span>'}</button>`}).join('')}</div>${memory.open.length===2?'<div class="arena-message wrong" role="status">Die beiden Begriffe passen noch nicht zusammen. Wähle eine weitere Karte, um es erneut zu versuchen.</div>':''}${memory.finished?'<div class="rw-feedback"><b>Alle Begriffe zugeordnet!</b><p>Du hast die wichtigen Fachwörter miteinander verbunden.</p></div>':''}<div class="inline" style="margin-top:17px">${btn('Neues Memo','memory:new','btn alt')}${btn('Andere Begriffe','memory:pack','btn ghost')}${btn('Zur Quiz-Arena','tab:arena','btn soft')}</div></div>`}
function rwWeatherSvg(){return''}
function rwDiagram(){const t=rw.station;if(t==='karte'){
 const n=rw.detail;
 let s=`<svg class="rw-svg" viewBox="0 0 740 400" role="img" aria-label="Schematische Stadtkarte; mit höherer Detailstufe werden kleine Straßen, Häuser und Bäume ergänzt."><defs><linearGradient id="landshade" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#e5f2dc"/><stop offset="1" stop-color="#c8e7c4"/></linearGradient></defs><rect width="740" height="400" rx="15" fill="url(#landshade)"/><path d="M0 300 Q85 240 160 270T320 205T485 240T740 144" fill="none" stroke="#83bce8" stroke-width="50"/><path d="M0 300 Q85 240 160 270T320 205T485 240T740 144" fill="none" stroke="#267aae" stroke-width="27"/><path d="M0 104 Q120 156 265 133T530 83T740 115 M50 400 Q137 295 250 273T555 305T740 323" fill="none" stroke="#fff4dc" stroke-width="25"/><path d="M0 104 Q120 156 265 133T530 83T740 115 M50 400 Q137 295 250 273T555 305T740 323" fill="none" stroke="#a76f57" stroke-width="3"/><path d="M232 133 L270 272 M555 90 L554 307" fill="none" stroke="#fff4dc" stroke-width="22"/>`;
 if(n>=2){s+=`<g fill="none" stroke="#ffffff" stroke-width="11"><path d="M63 50 L90 240 M140 35 L155 205 M354 30 L375 170 M457 20 L460 183 M625 10 L650 286 M270 395 L276 310"/><path d="M0 200 Q110 185 205 205 M390 344 L480 372 L650 350"/></g><g fill="none" stroke="#bf9880" stroke-width="2"><path d="M63 50 L90 240 M140 35 L155 205 M354 30 L375 170 M457 20 L460 183 M625 10 L650 286"/></g>`}
 if(n>=3){let houses=[[92,56],[178,78],[204,165],[325,44],[413,116],[516,36],[585,196],[390,350],[120,334],[668,240]];s+=`<g fill="#ce8980" stroke="#97585e" stroke-width="2">${houses.map(([x,y],i)=>`<rect x="${x}" y="${y}" width="${17+(i%2)*11}" height="${15+i%3*5}" rx="2"/>`).join('')}</g><rect x="300" y="282" width="32" height="32" rx="5" fill="#f6dd7b" stroke="#ac8720" stroke-width="2"/><text x="339" y="302" font-size="15" font-weight="700" fill="#304f3f">Schule</text>`}
 if(n>=4){s+=`<g fill="#44916c" stroke="#277456" stroke-width="2">${Array.from({length:24},(_,i)=>{let x=(i*71+17)%715,y=(i*113+25)%379;return `<circle cx="${x}" cy="${y}" r="${3+i%3}"/>`}).join('')}</g><g fill="#32576b" font-size="16" font-weight="750"><text x="28" y="87">Parkstraße</text><text x="520" y="68">Waldweg</text><text x="20" y="362">Feldweg</text></g>`}
 s+=`<rect x="12" y="13" width="205" height="44" rx="11" fill="#ffffffd9"/><text x="24" y="41" font-size="21" font-weight="800" fill="#204f5b">${n===1?'Übersichtskarte':n===2?'Regionalkarte':n===3?'Ortskarte':'Detaillierte Ortskarte'}</text></svg>`;return s;
 }
 if(t==='berg'){
 const h=rw.peak,w=rw.width,levels=[150,300,450,600,750];let y=x=>310-h/1000*236*Math.exp(-Math.pow((x-370)/w,2));const terrain=Array.from({length:71},(_,i)=>{let x=i*10+20;return `${i?'L':'M'}${x} ${y(x).toFixed(1)}`}).join(' ')+'L720 318 L20 318Z';let svg=`<svg class="rw-svg" viewBox="0 0 740 420" role="img" aria-label="Bergquerschnitt mit Höhenlinien und Grundriss. Je steiler der Berg, desto dichter die Höhenlinien."><rect width="740" height="420" fill="#f2faff"/><rect y="313" width="740" height="107" fill="#e4eed1"/><g stroke="#a9c2cc" stroke-dasharray="6 5">${levels.map(l=>`<line x1="20" y1="${310-l/1000*236}" x2="720" y2="${310-l/1000*236}"/>`).join('')}</g><path d="${terrain}" fill="#a6cf89" stroke="#357356" stroke-width="4"/><g fill="#28576a" font-size="16" font-weight="700">${levels.map(l=>`<text x="22" y="${306-l/1000*236}">${l} m</text>`).join('')}</g><line x1="30" y1="317" x2="720" y2="317" stroke="#745a46" stroke-width="3"/><text x="25" y="394" fill="#315b65" font-size="18">Bergprofil (Schema)</text>`;
 const left=levels.filter(l=>l<h).map(l=>{let r=w*Math.sqrt(Math.log(h/l));return {l,r}});
 svg+=`<g transform="translate(585 94)"><rect x="-115" y="-76" width="226" height="157" rx="12" fill="#ffffffed" stroke="#729ca8"/><text x="-96" y="-51" fill="#224e65" font-size="16" font-weight="800">Höhenlinien von oben</text>${left.map(({r,l},i)=>`<ellipse cx="0" cy="12" rx="${Math.min(r*.46,98).toFixed(1)}" ry="${Math.min(r*.25,53).toFixed(1)}" fill="none" stroke="${['#267b5a','#36895e','#927843','#ae663d','#b0473c'][i]}" stroke-width="3"/>`).join('')}<circle cx="0" cy="12" r="4" fill="#a64332"/></g><text x="330" y="${Math.max(48,y(370)-15)}" fill="#17374c" font-size="20" font-weight="850">${h} m</text></svg>`;
 return svg
 }
 if(t==='sonne'){
 const decl={summer:23.44,equinox:0,winter:-23.44}[rw.season],alt=90-Math.abs(rw.lat-decl),rad=alt*Math.PI/180;let sx=352+Math.cos(rad)*226,sy=301-Math.sin(rad)*228;return `<svg class="rw-svg" viewBox="0 0 740 420" role="img" aria-label="Sonnenstand zur Mittagszeit: modellhafter Winkel über dem Horizont für nördliche Breiten."><defs><linearGradient id="sunsky" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#0c497e"/><stop offset="1" stop-color="#b6def0"/></linearGradient><radialGradient id="sunglow"><stop stop-color="#fff8b5"/><stop offset=".52" stop-color="#fddd5a"/><stop offset="1" stop-color="#f6ac36"/></radialGradient></defs><rect width="740" height="300" fill="url(#sunsky)"/><rect y="300" width="740" height="120" fill="#8abb7f"/><path d="M0 335Q145 317 240 345T500 335T740 338V420H0Z" fill="#65a16f"/><line x1="70" y1="301" x2="672" y2="301" stroke="#fefce0" stroke-width="3" stroke-dasharray="8 6"/><text x="75" y="293" font-size="18" fill="white" font-weight="800">Horizont</text><circle cx="352" cy="301" r="7" fill="#ef6b55"/>${alt>0?`<line x1="352" y1="301" x2="${sx.toFixed(1)}" y2="${sy.toFixed(1)}" stroke="#fff2ac" stroke-width="5" stroke-dasharray="11 5"/>`:''}<circle cx="${sx.toFixed(1)}" cy="${sy.toFixed(1)}" r="34" fill="url(#sunglow)" stroke="#fff5c1" stroke-width="4"/>${alt>0?`<path d="M425 301 A73 73 0 0 0 ${(352+73*Math.cos(rad)).toFixed(1)} ${(301-73*Math.sin(rad)).toFixed(1)}" fill="none" stroke="#f9ffcf" stroke-width="3"/><text x="443" y="269" fill="#fff" font-size="22" font-weight="900">${alt.toFixed(1).replace('.',',')}°</text>`:`<text x="347" y="249" fill="#fff" font-size="18" font-weight="800" text-anchor="middle">Sonne unter dem Horizont</text>`}<text x="23" y="35" fill="#fff" font-size="21" font-weight="800">Modell: örtlicher Sonnenmittag · Nordhalbkugel</text><text x="22" y="390" fill="#174c38" font-size="19">Breitengrad ${rw.lat}° N · ${rw.season==='summer'?'Juni':rw.season==='winter'?'Dezember':'Tagundnachtgleiche'}</text></svg>`
 }
 // Koordinatenraster: bewusst ohne geographische Landformen, daher keine Scheinpräzision.
 let px=370+rw.gridLon/180*295,py=199-rw.gridLat/90*145;return `<svg class="rw-svg" viewBox="0 0 740 410" role="img" aria-label="Geografisches Raster mit beweglichem Zielpunkt; waagerechte Linien sind Breitenkreise, senkrechte sind Meridiane."><rect width="740" height="410" fill="#e8f6fa"/><rect x="75" y="40" width="590" height="318" rx="13" fill="#acd9eb" stroke="#286e95" stroke-width="3"/><g stroke="#e1f5fb" stroke-width="2">${[-60,-30,0,30,60].map(lat=>`<line x1="75" y1="${199-lat/90*145}" x2="665" y2="${199-lat/90*145}"/>`).join('')}${[-150,-120,-90,-60,-30,0,30,60,90,120,150].map(lon=>`<line x1="${370+lon/180*295}" y1="40" x2="${370+lon/180*295}" y2="358"/>`).join('')}</g><line x1="75" y1="199" x2="665" y2="199" stroke="#17698f" stroke-width="4"/><line x1="370" y1="40" x2="370" y2="358" stroke="#17698f" stroke-width="4"/><text x="81" y="190" fill="#114c6a" font-size="15" font-weight="800">Äquator</text><text x="383" y="58" fill="#114c6a" font-size="15" font-weight="800">Nullmeridian</text><circle cx="${px.toFixed(1)}" cy="${py.toFixed(1)}" r="12" fill="#e85447" stroke="white" stroke-width="4"/><line x1="${px-21}" y1="${py}" x2="${px+21}" y2="${py}" stroke="#a93632" stroke-width="2"/><line x1="${px}" y1="${py-21}" x2="${px}" y2="${py+21}" stroke="#a93632" stroke-width="2"/><rect x="192" y="364" width="356" height="36" rx="9" fill="#fafdff" stroke="#9ebdc8"/><text x="370" y="387" text-anchor="middle" fill="#194a65" font-size="20" font-weight="800">${coordLabel(rw.gridLat,true)}, ${coordLabel(rw.gridLon,false)}</text></svg>`
}
function rwObservation(){switch(rw.station){case'karte':return rw.detail===1?'Auf der Übersicht sind nur wichtige Straßen und der Fluss erkennbar.':rw.detail===4?'Auf der Detailkarte sind zusätzlich Gebäude, Straßennamen und Grünflächen zu erkennen.':`Auf Stufe ${rw.detail} sind einige, aber nicht alle Einzelheiten dargestellt.`;case'berg':return `Der Gipfel liegt bei ${rw.peak} m. Bei einer Modell-Hangbreite von ${rw.width} sind die Höhenlinien ${rw.width<=100?'relativ dicht':'weiter auseinander'}. Wichtig: Vergleiche immer gleiche Höhenabstände.`;case'sonne':{const d={summer:23.44,equinox:0,winter:-23.44}[rw.season],a=90-Math.abs(rw.lat-d);return `Auf ${rw.lat}° N beträgt die Mittagshöhe im Modell etwa ${a.toFixed(1).replace('.',',')}°. ${a<0?'Die Sonne steht hier selbst mittags unter dem Horizont.':'Der Sonnenhöchststand wird durch geografische Breite und Jahreszeit bestimmt.'}`}default:return`Der Zielpunkt liegt bei ${coordLabel(rw.gridLat,true)}, ${coordLabel(rw.gridLon,false)}. Zuerst wird die Breite, anschließend die Länge genannt.`}}
function rwRule(){switch(rw.station){case'karte':return 'Eine Karte muss für ihren Zweck lesbar bleiben. Generalisierung fasst zusammen oder lässt unwichtige Einzelheiten weg. Digitale Vergrößerung allein erzeugt keine zusätzlichen Informationen.';case'berg':return 'Höhenlinien verbinden Punkte gleicher Höhe. Bei gleichen Höhenabständen verlaufen sie auf steilen Hängen dichter und auf sanften Hängen weiter auseinander.';case'sonne':return 'Die Erdachse ist geneigt. Darum ändert sich die Höhe der Sonne zur Mittagszeit im Jahreslauf. Die Jahreszeiten entstehen nicht dadurch, dass die Erde im Sommer viel näher an der Sonne ist.';default:return 'Geografische Koordinaten bestehen aus Breite und Länge. Die Breite misst den Abstand vom Äquator nach Norden oder Süden, die Länge vom Nullmeridian nach Osten oder Westen.'}}
function researcherControls(){if(rw.station==='karte')return `<div class="field"><label for="detailRange">Generalisierung – wie viele Details werden gezeigt?</label><input class="rw-slider" data-rw="detail" id="detailRange" type="range" min="1" max="4" step="1" value="${rw.detail}"><span class="subtle mini">1 = Übersicht · 4 = viele Einzelheiten</span></div>`;if(rw.station==='berg')return `<div class="twofields"><div class="field"><label for="peakRange">Gipfelhöhe</label><input class="rw-slider" data-rw="peak" id="peakRange" type="range" min="500" max="900" step="100" value="${rw.peak}"></div><div class="field"><label for="widthRange">Breite des Berghangs</label><input class="rw-slider" data-rw="width" id="widthRange" type="range" min="60" max="220" step="20" value="${rw.width}"></div></div>`;if(rw.station==='sonne')return `<div class="twofields"><div class="field"><label for="latRange">Geografische Breite (Nordhalbkugel)</label><input class="rw-slider" data-rw="lat" id="latRange" type="range" min="0" max="70" step="5" value="${rw.lat}"></div><div class="field"><label for="seasonSel">Jahreszeit (vereinfachter Sonnenstand)</label><select class="rw-select" id="seasonSel" data-rw="season"><option value="summer" ${rw.season==='summer'?'selected':''}>Juni – Sommer auf der Nordhalbkugel</option><option value="equinox" ${rw.season==='equinox'?'selected':''}>März / September – Tagundnachtgleiche</option><option value="winter" ${rw.season==='winter'?'selected':''}>Dezember – Winter auf der Nordhalbkugel</option></select></div></div>`;return `<div class="twofields"><div class="field"><label for="gridLat">Breitengrad (− Süd / + Nord)</label><input class="rw-slider" id="gridLat" data-rw="gridLat" type="range" min="-60" max="60" step="10" value="${rw.gridLat}"></div><div class="field"><label for="gridLon">Längengrad (− West / + Ost)</label><input class="rw-slider" id="gridLon" data-rw="gridLon" type="range" min="-180" max="180" step="10" value="${rw.gridLon}"></div></div>`}
function researcherView(){let station=RESEARCH_STATIONS.find(s=>s.id===rw.station)||RESEARCH_STATIONS[0],log=rw.observed[rw.station],ans=rw.pred[rw.station];let seen=(progress.research||[]).length;return `<div class="rw-hero"><div class="eyebrow" style="color:#d4f7e7">Werde Geografie-Forscher</div><h1>🔬 Forscherwerkstatt</h1><p>Stelle eine Vermutung auf, verändere dein Modell und erkläre deine Beobachtung. Du darfst Dinge mehrfach ausprobieren – ein Experiment ist kein Test.</p><strong>${seen} von 4 Forscherstationen im Forschungsheft</strong></div><nav class="rw-toolbar" aria-label="Forscherstation wählen">${RESEARCH_STATIONS.map(s=>btn(s.emoji+' '+s.name,'research:station:'+s.id,'btn '+(s.id===rw.station?'on':'ghost')+' small')).join('')}</nav><div class="grid2"><section class="card"><div class="eyebrow">Station ${RESEARCH_STATIONS.findIndex(s=>s.id===rw.station)+1} von 4</div><h2>${station.emoji} ${station.name}</h2><p>${station.lead}</p><div class="rw-method"><div><b>1 · Vermuten</b>Überlege vor dem Experiment.</div><div><b>2 · Verändern</b>Bewege Regler und beobachte.</div><div><b>3 · Erklären</b>Vergleiche deine Vermutung mit dem Modell.</div></div><div class="rw-pred"><label for="researchGuess"><b>Was vermutest du?</b></label><select id="researchGuess" class="rw-select"><option value="">Bitte auswählen …</option>${station.options.map((v,i)=>`<option value="${i}" ${String(ans)===String(i)?'selected':''}>${esc(v)}</option>`).join('')}</select></div><h3 style="margin-top:22px">Experiment einstellen</h3>${researcherControls()}<div class="rw-note"><b>Beobachte:</b> <span id="researchReading">${esc(rwObservation())}</span></div><div class="inline" style="margin-top:15px">${btn('📋 Beobachtung auswerten','research:explain','btn alt')}${btn('↺ Versuchsaufbau zurücksetzen','research:reset','btn ghost')}</div>${log?`<div class="rw-feedback" role="status"><b>${log.pred===station.correct?'✅ Deine Vermutung passt zum Modell.':'🔎 Deine Vermutung war eine gute Forschungsfrage.'}</b><p>${esc(rwRule())}</p><p class="mini">Du kannst die Einstellungen jederzeit verändern und erneut auswerten.</p></div>`:''}</section><section class="card"><h2>Das siehst du im Modell</h2><div id="researchVisual">${rwDiagram()}</div><div class="rw-sample"><b>Mein Beobachtungsprotokoll:</b><p>Was ändert sich, wenn du genau einen Regler veränderst? Vergleiche mindestens zwei Einstellungen.</p></div><p class="subtle mini">Die Illustrationen sind schematische Modelle. Sie zeigen Zusammenhänge, ersetzen aber keine echten Messungen.</p></section></div><section class="card" style="margin-top:16px"><h2>📓 Mein Forscherheft</h2><div class="rw-grid">${RESEARCH_STATIONS.map(s=>`<div class="rw-plot"><b>${s.emoji} ${s.name}</b><p class="mini">${(progress.research||[]).includes(s.id)?'✅ Beobachtung ausgewertet':'Noch zu entdecken'}</p>${btn('Station öffnen','research:station:'+s.id,'btn ghost small')}</div>`).join('')}</div></section>`}
function updateResearchVisual(){const visual=document.getElementById('researchVisual');if(visual)visual.innerHTML=rwDiagram();const reading=document.getElementById('researchReading');if(reading)reading.textContent=rwObservation();const feedback=document.querySelector('.rw-feedback');if(feedback)feedback.remove()}
function researchHandle(target){const [_,cmd,val]=target.split(':');if(cmd==='station'){rw.station=val;state.tab='workshop';render();return}if(cmd==='reset'){let station=rw.station;rw={...rw,...{detail:3,peak:800,width:140,lat:50,season:'summer',gridLat:30,gridLon:40}};rw.observed[station]=null;render();return}if(cmd==='explain'){const pick=document.getElementById('researchGuess')?.value;if(pick===''||pick===undefined){msg('Wähle zuerst eine Vermutung aus.');document.getElementById('researchGuess')?.focus();return}rw.pred[rw.station]=Number(pick);rw.observed[rw.station]={pred:Number(pick)};progress.research=progress.research||[];if(!progress.research.includes(rw.station)){progress.research.push(rw.station);progress.stars+=5;save()}render();return}}

/* Erweiterte Navigation: bestehende Lernpfade, Lernstand und lokale Speicherung bleiben erhalten. */
const newTabs=[['workshop','🔬 Forscherwerkstatt'],['arena','⚡ Blitz-Quiz'],['memo','🧩 Geo-Memo']];
const tabRoot=document.getElementById('tabs');const gamesTab=tabRoot.querySelector('[data-tab="games"]');
newTabs.forEach(([id,label])=>{const el=document.createElement('button');el.type='button';el.dataset.tab=id;el.textContent=label;gamesTab.insertAdjacentElement('beforebegin',el)});
const savedRender=render;
render=function(){if(['workshop','arena','memo'].includes(state.tab)){
 updateStars();document.documentElement.dataset.theme=progress.theme;document.documentElement.dataset.contrast=progress.contrast;document.documentElement.style.setProperty('--fontScale',String(progress.font));document.querySelectorAll('#tabs button').forEach(b=>{b.classList.toggle('active',b.dataset.tab===state.tab);b.setAttribute('aria-current',b.dataset.tab===state.tab?'page':'false')});
 const html=state.tab==='workshop'?researcherView():state.tab==='arena'?arenaView():memoryView();MAIN.innerHTML=`<div class="flash">${html}</div>`;
 if(state.tab==='arena'&&arena.phase==='play'&&!arena.done&&arena.seconds)arenaClock();return
 }savedRender();};
const savedStart=renderStart;
renderStart=function(){return savedStart()+`<h2 class="section-title">Neu: Entdecken, Spielen, Verstehen</h2><div class="grid"><section class="card rw-station-card"><div class="module-icon">🔬</div><h3>Forscherwerkstatt</h3><p>Vier veränderbare Versuchsmodelle mit Vermutung, Beobachtung und Auswertung.</p>${btn('Jetzt experimentieren →','tab:workshop','btn alt')}</section><section class="card rw-station-card"><div class="module-icon">⚡</div><h3>Blitz-Quiz</h3><p>Vier farbige Antwortfelder, freiwilliger Timer und Punktebonus.</p>${btn('Quizduell starten →','tab:arena','btn alt')}</section><section class="card rw-station-card"><div class="module-icon">🧩</div><h3>Geo-Memo</h3><p>Fachbegriffe und Erklärungen im Gedächtnisspiel zusammenbringen.</p>${btn('Memo spielen →','tab:memo','btn alt')}</section></div>`}
const savedGames=renderGames;
renderGames=function(){return savedGames()+`<h2 class="section-title">Weitere Spiele</h2><div class="grid"><div class="card"><h3>⚡ Blitz-Quiz-Arena</h3><p>Wie beim Quizduell: Auswahlkarten, Punkte, Zeitdruck optional.</p>${btn('Arena öffnen','tab:arena','btn alt')}</div><div class="card"><h3>🧩 Geo-Memo</h3><p>Spiele mit 12 verdeckten Karten und festige Fachbegriffe.</p>${btn('Memo starten','tab:memo','btn alt')}</div><div class="card"><h3>🎓 Expertenfragen</h3><p>Knifflige geografische Denkfragen – nicht nur Auswendiglernen.</p>${btn('Profirunde starten','arena:deep','btn alt')}</div></div>`}
const savedLesson=renderLesson;
renderLesson=function(){let base=savedLesson();return base+`<div class="lesson-deep"><h3>🧠 Mehr als Auswendiglernen</h3><p>Übe die Anwendung des Wissens in kniffligen Alltagssituationen. Im Blitz-Quiz sind auch fortgeschrittene Denkfragen enthalten.</p>${btn('Anspruchsvolle Übungsrunde','arena:topic:'+state.topic,'btn alt')}${btn('Forscherwerkstatt öffnen','tab:workshop','btn ghost')}</div>`}
const savedSwitch=switchTab;
switchTab=function(tab){clearArenaClock();savedSwitch(tab);if(tab==='memo'&&!memory.deck.length)newMemory()};
const savedAction=action;
action=function(target){const [a,b,c]=target.split(':');if(a==='research'){researchHandle(target);return}if(a==='arena'){
 if(b==='answer'){answerArena(Number(c));return}
 if(b==='next'){nextArena();return}
 if(b==='start'){arena.topic=document.getElementById('arenaTopic')?.value||'all';arena.size=Number(document.getElementById('arenaSize')?.value||10);arena.seconds=Number(document.getElementById('arenaSeconds')?.value??25);newArena();return}
 if(b==='deep'){arena.topic='all';arena.size=10;arena.seconds=0;newArena(true);state.tab='arena';render();return}
 if(b==='topic'){arena.topic=c;arena.size=10;arena.seconds=0;newArena(false);state.tab='arena';render();return}
 if(b==='restart'){arena.phase='setup';state.tab='arena';render();return}
 if(b==='exit'){arena.phase='setup';clearArenaClock();state.tab='arena';render();return}
 }
 if(a==='memory'){if(b==='new'){newMemory();return}if(b==='pack'){memory.pack=(memory.pack+1)%MEMORY_SETS.length;newMemory();return}if(b==='pick'){memoryPick(Number(c));return}}
 savedAction(target);
};
MAIN.addEventListener('input',e=>{const k=e.target?.dataset?.rw;if(k&&k!=='season'){rw[k]=Number(e.target.value);rw.observed[rw.station]=null;updateResearchVisual()}});
MAIN.addEventListener('change',e=>{if(e.target?.dataset?.rw==='season'){rw.season=e.target.value;rw.observed[rw.station]=null;updateResearchVisual()}});
newMemory();

render();